script.on_init(function() local f=game.forces.player;f.research_all_technologies();local t=f.technologies[name];if not t then fail("runtime MIR Imersite technology absent") end;t.level=1;f.research_queue={t};if not f.current_research or f.current_research.name~=name then fail("fractional research could not be established") end;f.research_progress=0.42;storage.mir4_a05={level=t.level,progress=0.42} end)
